//! Finite original-request Office edits. No generated paths or grants.
use super::*;
use crate::native_office_revision::{OfficeRevisionEdit as E,OfficeRevisionPreview,render_office_revision,render_office_revision_batch};
use serde_json::Value;
use std::{io::{Cursor,Read},collections::BTreeMap};
#[derive(Debug)] pub(super) enum Edits{Text{old:String,new:String,all:bool},Cells(Vec<E>)}
fn scalar_prefix(s:&str)->Option<(Value,&str)>{let end=if s.starts_with('"'){let mut escaped=false;let mut end=None;for (i,c) in s.char_indices().skip(1){if escaped{escaped=false;continue}if c=='\\'{escaped=true}else if c=='"'{end=Some(i+1);break}}end?}else{s.find([' ',';']).unwrap_or(s.len())};Some((serde_json::from_str(&s[..end]).ok()?,&s[end..]))}
fn number(v:&serde_json::Number)->Option<f64>{let n=v.as_f64()?;if !n.is_finite()||n.abs()>9_007_199_254_740_991.0{return None}Some(n)}
fn text_ok(s:&str)->bool{!s.trim().is_empty()&&s.len()<=512&&!s.chars().any(|c|c.is_control()||unsafe_display(c))}
fn cell(s:&str)->Option<(E,&str)>{let s=s.strip_prefix("change cell ")?;let (addr,s)=s.split_once(" on sheet ")?;if addr.len()>8||addr.is_empty()||!addr.bytes().all(|b|b.is_ascii_uppercase()||b.is_ascii_digit()){return None}
 let (sheet,s)=s.split_once(" from ")?;let sheet_number:usize=sheet.parse().ok()?;if !(1..=256).contains(&sheet_number){return None}let (old,s)=scalar_prefix(s)?;let (new,rest)=scalar_prefix(s.strip_prefix(" to ")?)?;if old==new{return None}let address=addr.to_owned();let e=match (old,new){(Value::Number(a),Value::Number(b))=>E::CellNumber{sheet_number,address,expected_old:number(&a)?,new_number:number(&b)?},(Value::Bool(a),Value::Bool(b))=>E::CellBoolean{sheet_number,address,expected_old:a,new_boolean:b},(Value::String(a),Value::String(b)) if text_ok(&a)&&text_ok(&b)=>E::CellInlineText{sheet_number,address,expected_old:a,new_text:b},_=>return None};Some((e,rest))}
pub(super) fn parse(s:&str)->Option<(String,Edits)>{let (name,tail)=s.strip_prefix("Revise ").or_else(||s.strip_prefix("revise "))?.split_once(": ")?;if !leaf(name){return None}let ext=name.rsplit_once('.')?.1.to_ascii_lowercase();let tail=tail.strip_suffix('.').unwrap_or(tail);
 if ext=="docx"||ext=="pptx"{let (all,tail)=if let Some(t)=tail.strip_prefix("replace all "){(true,t)}else{(false,tail.strip_prefix("replace ")?)};let (old,rest)=scalar_prefix(tail)?;let new:Value=serde_json::from_str(rest.strip_prefix(" with ")?).ok()?;let (old,new)=(old.as_str()?,new.as_str()?);if !text_ok(old)||!text_ok(new)||old==new{return None}Some((name.into(),Edits::Text{old:old.into(),new:new.into(),all}))}
 else if ext=="xlsx"{let mut edits=Vec::new();let mut tail=tail;loop{let (edit,rest)=cell(tail)?;edits.push(edit);if edits.len()>4{return None}if rest.is_empty(){break}tail=rest.strip_prefix("; ")?;}Some((name.into(),Edits::Cells(edits)))}else{None}}
impl Edits{pub(super) fn batch(&self)->bool{match self{Self::Text{all,..}=>*all,Self::Cells(e)=>e.len()>1}}
 pub(super) fn preview(&self,ext:&str,original:&[u8],digest:&str)->Result<(Vec<E>,OfficeRevisionPreview),String>{let edits=match self{Self::Cells(e)=>e.clone(),Self::Text{old,new,all}=>{let e=if ext=="docx"{crate::native_office_replace_all::plan_word_run_replace_all(original,digest,old,new).map(|r|r.edits)}else{crate::native_office_replace_all::plan_presentation_run_replace_all(original,digest,old,new).map(|r|r.edits)}.map_err(|_|"No safe exact replacement found")?;if !all&&e.len()!=1{return Err("More than one matching text occurrence. Specify replace all or use the revision review panel.".into())}e}};let result=if self.batch(){render_office_revision_batch(original,digest,&edits)}else{render_office_revision(original,digest,&edits[0])}.map_err(|_|"The exact edits cannot be applied safely")?;Ok((edits,result))}}
fn change(e:&E)->proto::office_revision_request::Change{use proto::office_revision_request::Change as C;match e{E::WordRun{text_index,expected_old,new_text}=>C::WordText(proto::OfficeTextPatch{text_index:*text_index as u32,slide_number:0,expected_old:expected_old.clone(),new_text:new_text.clone()}),E::SlideRun{slide_number,text_index,expected_old,new_text}=>C::SlideText(proto::OfficeTextPatch{text_index:*text_index as u32,slide_number:*slide_number as u32,expected_old:expected_old.clone(),new_text:new_text.clone()}),E::CellNumber{sheet_number,address,expected_old,new_number}=>C::CellNumber(proto::OfficeNumberPatch{sheet_number:*sheet_number as u32,address:address.clone(),expected_old:*expected_old,new_number:*new_number}),E::CellBoolean{sheet_number,address,expected_old,new_boolean}=>C::CellBoolean(proto::OfficeBooleanPatch{sheet_number:*sheet_number as u32,address:address.clone(),expected_old:*expected_old,new_boolean:*new_boolean}),E::CellInlineText{sheet_number,address,expected_old,new_text}=>C::CellText(proto::OfficeStringPatch{sheet_number:*sheet_number as u32,address:address.clone(),expected_old:expected_old.clone(),new_text:new_text.clone()})}}
pub(super) fn targeted(edits:&[E])->std::collections::BTreeSet<String>{edits.iter().map(|e|match e{E::WordRun{..}=>"word/document.xml".into(),E::SlideRun{slide_number,..}=>format!("ppt/slides/slide{slide_number}.xml"),E::CellNumber{sheet_number,..}|E::CellBoolean{sheet_number,..}|E::CellInlineText{sheet_number,..}=>format!("xl/worksheets/sheet{sheet_number}.xml")}).collect()}
pub(super) fn check_order(ext:&str,original:&[u8],targets:&std::collections::BTreeSet<String>)->bool{
 if ext=="docx"{return true}let Ok(paths)=crate::native_reader_office::ordered_revision_parts(original,ext)else{return false};
 paths.iter().enumerate().all(|(i,p)|*p==if ext=="pptx"{format!("ppt/slides/slide{}.xml",i+1)}else{format!("xl/worksheets/sheet{}.xml",i+1)})&&targets.iter().all(|p|paths.contains(p))
}
pub(super) fn request(batch:bool,source:&str,target:&str,old:&str,new:&str,edits:&[E])->ProtoPayload{use proto::{office_revision_request::Change as C,office_batch_patch::Change as B};if batch{let patches=edits.iter().map(|e|proto::OfficeBatchPatch{change:Some(match change(e){C::WordText(p)=>B::WordText(p),C::SlideText(p)=>B::SlideText(p),C::CellNumber(p)=>B::CellNumber(p),C::CellBoolean(p)=>B::CellBoolean(p),C::CellText(p)=>B::CellText(p)})}).collect();ProtoPayload{type_url:crate::native_office_batch_tool::INPUT.into(),bytes:proto::OfficeBatchRevisionRequest{source_name:source.into(),target_new_name:target.into(),original_sha256:old.into(),approved_revised_sha256:new.into(),patches}.encode_to_vec()}}else{ProtoPayload{type_url:crate::native_office_revision_tool::INPUT.into(),bytes:proto::OfficeRevisionRequest{source_name:source.into(),target_new_name:target.into(),original_sha256:old.into(),approved_revised_sha256:new.into(),change:Some(change(&edits[0]))}.encode_to_vec()}}}
pub(super) fn display(e:&E)->String{match e{E::WordRun{text_index,expected_old,new_text}=>format!("Word text occurrence {}: {} → {}",text_index+1,json!(expected_old),json!(new_text)),E::SlideRun{slide_number,text_index,expected_old,new_text}=>format!("Slide {slide_number}, text occurrence {}: {} → {}",text_index+1,json!(expected_old),json!(new_text)),E::CellNumber{sheet_number,address,expected_old,new_number}=>format!("Sheet {sheet_number}, {address}: {expected_old} → {new_number}"),E::CellBoolean{sheet_number,address,expected_old,new_boolean}=>format!("Sheet {sheet_number}, {address}: {expected_old} → {new_boolean}"),E::CellInlineText{sheet_number,address,expected_old,new_text}=>format!("Sheet {sheet_number}, {address}: {} → {}",json!(expected_old),json!(new_text))}}
/// Independent uncompressed ZIP member witness, bounded to the artifact inspector's limits.
pub(super) fn parts(data:&[u8])->Option<BTreeMap<String,String>>{let mut z=zip::ZipArchive::new(Cursor::new(data)).ok()?;if z.len()>512{return None}let mut total=0u64;let mut out=BTreeMap::new();for i in 0..z.len(){let mut f=z.by_index(i).ok()?;let n=f.name().ok()?.into_owned();total=total.checked_add(f.size())?;if total>32*1024*1024{return None}let mut bytes=Vec::new();(&mut f).take(32*1024*1024+1).read_to_end(&mut bytes).ok()?;if bytes.len() as u64!=f.size()||out.insert(n,sha(&bytes)).is_some(){return None}}Some(out)}
pub(super) fn read(root:&Dir,n:&str)->Option<Vec<u8>>{let meta=root.symlink_metadata(n).ok()?;if !meta.is_file()||meta.file_type().is_symlink()||meta.len()>1024*1024{return None}#[cfg(windows)]{use cap_std::fs::MetadataExt;if meta.file_attributes()&0x400!=0{return None}}let b=crate::native_artifact_inspect::read_bounded(root,n).ok()?;if b.len()>1024*1024{return None}Some(b)}
